-- Additive, public art circles. Existing region posts remain intact.
CREATE TABLE IF NOT EXISTS cv_circles(id TEXT PRIMARY KEY,owner_id TEXT REFERENCES cv_members(id),name TEXT NOT NULL,description TEXT NOT NULL,craft TEXT NOT NULL,region TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',cover TEXT NOT NULL DEFAULT '',search TEXT NOT NULL DEFAULT '',rules TEXT NOT NULL DEFAULT 'Be kind. Credit artists. Share work you have permission to publish.',request_key TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(owner_id,request_key));
CREATE INDEX IF NOT EXISTS cv_circles_discovery ON cv_circles(status,craft,region,created_at);
CREATE TABLE IF NOT EXISTS cv_circle_follows(circle_id TEXT NOT NULL REFERENCES cv_circles(id),member_id TEXT NOT NULL REFERENCES cv_members(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(circle_id,member_id));
CREATE INDEX IF NOT EXISTS cv_circle_follows_member ON cv_circle_follows(member_id,circle_id);
CREATE TABLE IF NOT EXISTS cv_circle_posts(circle_id TEXT NOT NULL REFERENCES cv_circles(id),post_id TEXT NOT NULL REFERENCES cv_posts(id),PRIMARY KEY(circle_id,post_id));
CREATE INDEX IF NOT EXISTS cv_circle_posts_post ON cv_circle_posts(post_id,circle_id);
